export function padStart(input, n = 2) {
  const isNeg = input < 0;
  let padded = isNeg ? (-input).toString() : input.toString();
  if (padded.length < n) {
    padded = ("0".repeat(n) + padded).slice(-n);
  }
  return isNeg ? "-" + padded : padded;
}

